package com.yuegang.zhihui.common.mq;import java.nio.charset.StandardCharsets;import org.apache.rocketmq.client.producer.*;import org.apache.rocketmq.common.message.Message;public final class RocketMqDomainEventPublisher implements DomainEventPublisher{private final DefaultMQProducer producer;private final String topic;public RocketMqDomainEventPublisher(String group,String nameserver,String topic){this.topic=topic;try{producer=new DefaultMQProducer(group);producer.setNamesrvAddr(nameserver);producer.setRetryTimesWhenSendFailed(2);producer.setSendMsgTimeout(3000);producer.start();}catch(Exception e){throw new IllegalStateException("RocketMQ producer startup failed",e);}}public void publish(String eventId,String aggregateId,String eventType,String payload){try{Message m=new Message(topic,eventType,eventId,payload.getBytes(StandardCharsets.UTF_8));m.putUserProperty("eventId",eventId);m.putUserProperty("aggregateId",aggregateId);m.putUserProperty("eventType",eventType);m.putUserProperty("schemaVersion","1");SendResult result=producer.send(m);if(result.getSendStatus()!=SendStatus.SEND_OK)throw new IllegalStateException("RocketMQ send status "+result.getSendStatus());}catch(Exception e){throw new MessageInfrastructureException("RocketMQ event publish failed",e);}}public void close(){producer.shutdown();}}
